import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { ShoppingBag, User, LogOut, Sun, Moon, Menu as MenuIcon, X } from "lucide-react";
import { useCart } from "../context/CartContext";
import { useAuth } from "../context/AuthContext";
import { useTheme } from "../context/ThemeContext";

export default function Header({ onCartClick }) {
  const { count } = useCart();
  const { user, logout } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const navigate = useNavigate();
  const [mobileOpen, setMobileOpen] = useState(false);

  return (
    <header
      style={{
        position: "sticky",
        top: 0,
        zIndex: 40,
        background: "var(--card)",
        borderBottom: "1px solid var(--border)",
      }}
    >
      <div className="container header-inner" style={{ padding: "14px 24px", display: "flex", alignItems: "center", justifyContent: "space-between" }}>
        <Link to="/" className="focus-ring" style={{ display: "flex", alignItems: "center", gap: 10 }}>
          <span
            style={{
              width: 34,
              height: 34,
              borderRadius: "50%",
              background: "linear-gradient(150deg, var(--leaf), #8B5CF6)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              boxShadow: "0 2px 8px rgba(0,0,0,0.4)",
            }}
          >
            <TiffinMark />
          </span>
          <span className="disp" style={{ fontSize: 19, fontWeight: 600, color: "var(--leaf-deep)", letterSpacing: "-0.01em" }}>
            Healthy<span className="disp-i" style={{ color: "var(--leaf)" }}>Food</span>
          </span>
        </Link>

        <button
          type="button"
          className="mobile-menu-toggle focus-ring"
          onClick={() => setMobileOpen((v) => !v)}
          aria-label={mobileOpen ? "Close menu" : "Open menu"}
          aria-expanded={mobileOpen}
        >
          {mobileOpen ? <X size={21} /> : <MenuIcon size={21} />}
        </button>

        <nav className={`site-nav ${mobileOpen ? "mobile-open" : ""}`} style={{ display: "flex", gap: 4, alignItems: "center" }}>
          <NavLink to="/menu">Menu</NavLink>
          <NavLink to="/orders">Track Order</NavLink>
          {user?.role === "admin" && <NavLink to="/admin">Admin</NavLink>}

          {user ? (
            <button
              onClick={() => {
                logout();
                navigate("/");
              }}
              className="focus-ring"
              title="Log out"
              style={{
                marginLeft: 8,
                display: "flex",
                alignItems: "center",
                gap: 6,
                padding: "8px 14px",
                borderRadius: 999,
                border: "1px solid var(--border)",
                background: "var(--panel)",
                fontSize: 13.5,
                fontWeight: 700,
                color: "var(--ink)",
              }}
            >
              <User size={15} /> {user.name.split(" ")[0]} <LogOut size={13} />
            </button>
          ) : (
            <NavLink to="/login">Log in</NavLink>
          )}

          <button
            onClick={toggleTheme}
            className="focus-ring"
            title={theme === "light" ? "Switch to Dark theme" : "Switch to Light theme"}
            aria-label={theme === "light" ? "Switch to Dark theme" : "Switch to Light theme"}
            style={{
              marginLeft: 8,
              width: 38,
              height: 38,
              borderRadius: "50%",
              border: "1px solid var(--border)",
              background: "var(--panel)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            {theme === "light" ? <Moon size={16} color="var(--leaf)" /> : <Sun size={16} color="var(--turmeric)" />}
          </button>

          <button
            onClick={onCartClick}
            className="focus-ring"
            style={{
              position: "relative",
              marginLeft: 8,
              width: 38,
              height: 38,
              borderRadius: "50%",
              border: "1px solid var(--border)",
              background: "var(--panel)",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <ShoppingBag size={17} color="var(--leaf)" />
            {count > 0 && (
              <span
                style={{
                  position: "absolute",
                  top: -4,
                  right: -4,
                  background: "var(--chili)",
                  color: "#FFFFFF",
                  fontSize: 11,
                  fontWeight: 800,
                  borderRadius: 999,
                  minWidth: 18,
                  height: 18,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  padding: "0 4px",
                }}
              >
                {count}
              </span>
            )}
          </button>
        </nav>
      </div>
    </header>
  );
}

function TiffinMark() {
  return (
    <svg width="19" height="19" viewBox="0 0 24 24" fill="none">
      <path d="M12 4c-4.4 0-7.6 3-7.6 6.9 0 3.2 2.4 5.9 5.5 5.9 0 0-1.5-2.1-0.2-4 1.3-2 -0.7-3.7 0.9-6C11.3 5.9 12 4 12 4Z" stroke="#FFFFFF" strokeWidth="1.5" strokeLinejoin="round"/>
      <path d="M12 4c0 0 0.7 1.9-0.9 4.8-1.6 2.3 0.4 4-0.9 6-1.3 1.9 0.2 4 0.2 4" stroke="var(--chili)" strokeWidth="1" opacity="0.7"/>
      <path d="M15.5 8.5q1 -1.6 -0.4 -3.6" stroke="#FFFFFF" strokeWidth="1.4" strokeLinecap="round" opacity="0.7"/>
    </svg>
  );
}

function NavLink({ to, children }) {
  return (
    <Link
      to={to}
      className="focus-ring"
      style={{
        padding: "8px 14px",
        borderRadius: 999,
        fontSize: 14,
        fontWeight: 600,
        color: "var(--ink-soft)",
      }}
    >
      {children}
    </Link>
  );
}
